package com.example.starter.costmap;

/**
 * 业务可预测错误基类；映射为稳定的 HTTP 状态码与错误码。
 */
public class CostmapException extends RuntimeException {

    private final String code;

    public CostmapException(String code, String message) {
        super(message);
        this.code = code;
    }

    public String code() {
        return code;
    }
}

package com.example.starter.costmap;

/**
 * 请求区域非法（坐标反转、为空或越界），HTTP 400。
 */
public class InvalidRegionException extends CostmapException {

    public InvalidRegionException(String message) {
        super("INVALID_REGION", message);
    }
}

package com.example.starter.costmap;

/**
 * 地图或快照版本不存在，HTTP 404。
 */
public class VersionNotFoundException extends CostmapException {

    public VersionNotFoundException(String message) {
        super("VERSION_NOT_FOUND", message);
    }
}

package com.example.starter.costmap;

/**
 * 版本冲突或幂等请求异参重放，HTTP 409。
 */
public class ConflictException extends CostmapException {

    public ConflictException(String code, String message) {
        super(code, message);
    }
}

